#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# DockPeek: sets up signed + notarized GitHub releases.
# Secrets go straight from your files/keyboard to GitHub's "release" environment
# with `gh`; nothing is printed or written to .env. Run from the repo root.

TOTAL_STAGES=5
REPO="${REPO:-$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || echo badriram/dockpeek)}"
ENVIRONMENT=release

# env_secret NAME — set a secret in the release environment from stdin.
env_secret() {
  if gh secret set "$1" --env "$ENVIRONMENT" -R "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("$1")
    printf '  %s✓ set%s %s (environment: %s)\n' "$GREEN" "$RESET" "$1" "$ENVIRONMENT"
  else
    SKIPPED+=("secret $1 in environment $ENVIRONMENT")
    warn "failed to set $1"
  fi
}

expand_path() { local p="$1"; printf '%s' "${p/#\~/$HOME}"; }

has_devid() { security find-identity -v -p codesigning 2>/dev/null | grep -q "Developer ID Application"; }

command -v gh >/dev/null && gh auth status >/dev/null 2>&1 \
  || { echo "Install GitHub CLI and run 'gh auth login' first."; exit 1; }

banner "DockPeek · signed releases for $REPO"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
if has_devid; then
  say "Found a Developer ID Application certificate in your keychain. Nothing to do."
  pause
else
  say "This certificate signs apps distributed outside the App Store."
  note "Only the Account Holder of your Apple Developer team can create it."
  open -a Xcode 2>/dev/null || warn "couldn't open Xcode; open it manually"
  step "Xcode → Settings… (⌘,) → Accounts."
  step "Select your Apple ID, then your team → Manage Certificates…"
  step "Click + (bottom left) → Developer ID Application. Close the sheet."
  until has_devid; do
    pause "Press Enter once it's created…"
    has_devid || warn "Not found in your keychain yet. Try again (or Ctrl-C to stop)."
  done
  printf '  %s✓ found%s Developer ID Application certificate\n' "$GREEN" "$RESET"
  pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Export the certificate (.p12)"
say "CI needs the certificate and its private key, exported with a password."
open -a "Keychain Access" 2>/dev/null || warn "couldn't open Keychain Access; open it manually"
step "Keychain Access → login keychain → My Certificates."
step "Find 'Developer ID Application: …'. Expand it: a private key must be under it."
step "Right-click the certificate (not the key) → Export…"
step "Format: Personal Information Exchange (.p12). Save to Desktop as DockPeek-DeveloperID.p12"
step "Choose a strong export password (store it in your password manager)."
pause "Press Enter once exported…"
ask P12_PATH "Path to the .p12 [~/Desktop/DockPeek-DeveloperID.p12]:"
P12_PATH=$(expand_path "${P12_PATH:-~/Desktop/DockPeek-DeveloperID.p12}")
while [[ ! -f "$P12_PATH" ]]; do
  warn "No file at $P12_PATH"
  ask P12_PATH "Path to the .p12:"; P12_PATH=$(expand_path "$P12_PATH")
done
ask_secret P12_PASSWORD "Export password (hidden):"
subjects=$(P12_PASSWORD="$P12_PASSWORD" openssl pkcs12 -in "$P12_PATH" -nokeys -passin env:P12_PASSWORD 2>/dev/null \
  | grep -E "^subject" || true)
if [[ -z "$subjects" ]]; then
  warn "Couldn't read the .p12 (wrong password, or an openssl format issue)."
  confirm "Continue anyway?" || exit 1
elif [[ $(grep -c . <<<"$subjects") -ne 1 ]] || ! grep -q "Developer ID Application" <<<"$subjects"; then
  warn "The .p12 should contain exactly one 'Developer ID Application' certificate. It contains:"
  note "$subjects"
  confirm "Upload it anyway?" || exit 1
else
  printf '  %s✓ verified%s one Developer ID Application certificate\n' "$GREEN" "$RESET"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (notarization)"
say "CI uses this key to send builds to Apple's notary service."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Users and Access → Integrations → App Store Connect API → Team Keys."
step "First time only: click Request Access and accept the terms."
step "Click + (Generate API Key). Name: DockPeek notarization. Access: Developer."
step "Copy the Issuer ID shown above the keys table."
ask ASC_ISSUER_ID "Issuer ID:"
step "Copy the new key's Key ID from its row."
ask ASC_KEY_ID "Key ID:"
step "Click Download on that key. Apple lets you download it only once."
pause "Press Enter once downloaded…"
ask P8_PATH "Path to the .p8 [~/Downloads/AuthKey_${ASC_KEY_ID}.p8]:"
P8_PATH=$(expand_path "${P8_PATH:-~/Downloads/AuthKey_${ASC_KEY_ID}.p8}")
until [[ -f "$P8_PATH" ]] && head -1 "$P8_PATH" | grep -q "BEGIN PRIVATE KEY"; do
  warn "No private key file at $P8_PATH"
  ask P8_PATH "Path to the .p8:"; P8_PATH=$(expand_path "$P8_PATH")
done
printf '  %s✓ found%s API key file\n' "$GREEN" "$RESET"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub: protected 'release' environment + secrets"
say "Secrets go into an environment that only v* tags can use, so a branch or"
say "pull request can never read them."
confirm "Create/update environment '$ENVIRONMENT' on $REPO?" || exit 1
REVIEWERS='[]'
if confirm "Require your approval in GitHub before each release job runs? (recommended)"; then
  REVIEWERS="[{\"type\":\"User\",\"id\":$(gh api user --jq .id)}]"
fi
gh api -X PUT "repos/$REPO/environments/$ENVIRONMENT" --input - >/dev/null <<JSON
{"reviewers": $REVIEWERS,
 "deployment_branch_policy": {"protected_branches": false, "custom_branch_policies": true}}
JSON
gh api -X POST "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
  -f name='v*' -f type=tag >/dev/null 2>&1 || true
printf '  %s✓ environment%s %s (deploys only from v* tags)\n' "$GREEN" "$RESET" "$ENVIRONMENT"
base64 -i "$P12_PATH" | env_secret MACOS_CERT_P12_BASE64
printf '%s' "$P12_PASSWORD" | env_secret MACOS_CERT_PASSWORD
base64 -i "$P8_PATH" | env_secret ASC_KEY_P8_BASE64
printf '%s' "$ASC_KEY_ID" | env_secret ASC_KEY_ID
printf '%s' "$ASC_ISSUER_ID" | env_secret ASC_ISSUER_ID
unset P12_PASSWORD
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Clean up local copies"
say "GitHub now holds encrypted copies. The files on disk are no longer needed."
note "The certificate stays in your keychain, so you can export a new .p12 any time."
warn "The .p8 can't be downloaded again. Keep a copy in your password manager,"
warn "or plan to revoke it and generate a new key if you ever need it."
if confirm "Delete $P12_PATH and $P8_PATH now?"; then
  rm -f "$P12_PATH" "$P8_PATH"
  printf '  %s✓ deleted%s local .p12 and .p8\n' "$GREEN" "$RESET"
else
  SKIPPED+=("delete $P12_PATH and $P8_PATH once stored safely")
fi
pause

finish
say "To publish a release:"
step "git tag v0.1.0 && git push origin v0.1.0"
note "Then approve it under Actions if you required approval. Users can verify a download with:"
note "  gh attestation verify DockPeek-v0.1.0.zip -R $REPO"
printf '\n'
